NSColor *C(unsigned h){return [NSColor colorWithSRGBRed:((h>>16)&255)/255.0 green:((h>>8)&255)/255.0 blue:(h&255)/255.0 alpha:1];}
void text(NSString*s,NSRect r,CGFloat size,NSColor*c){NSMutableParagraphStyle *p=[NSMutableParagraphStyle new];p.alignment=NSTextAlignmentCenter;NSFont*f=[NSFont fontWithName:@"Thonburi-Bold" size:size]?:[NSFont boldSystemFontOfSize:size];[s drawInRect:r withAttributes:@{NSFontAttributeName:f,NSForegroundColorAttributeName:c,NSParagraphStyleAttributeName:p}];}
