void symbol(NSString*name,NSRect rect,NSColor*c){NSImage*img=[NSImage imageWithSystemSymbolName:name accessibilityDescription:nil];NSImage *tinted=[[NSImage alloc]initWithSize:rect.size];[tinted lockFocus];[img drawInRect:NSMakeRect(0,0,rect.size.width,rect.size.height)];[c set];NSRectFillUsingOperation(NSMakeRect(0,0,rect.size.width,rect.size.height),NSCompositingOperationSourceIn);[tinted unlockFocus];[tinted drawInRect:rect];}
