NSArray*states=@[@"primary",@"hover",@"gold",@"disabled"];NSArray*colors=@[g,n,gold,C(0xD9DFD5)];for(int i=0;i<4;i++){image([out stringByAppendingPathComponent:[NSString stringWithFormat:@"button-%@.png",states[i]]],720,144,^{NSBezierPath*p=[NSBezierPath bezierPathWithRoundedRect:NSMakeRect(2,2,716,140) xRadius:28 yRadius:28];[colors[i]setFill];[p fill];});}
NSArray*ts=@[@"available",@"selected",@"pending",@"confirmed"];NSArray*tc=@[C(0xE8F2E8),g,C(0xF2CF82),C(0xBC6759)];for(int i=0;i<4;i++){image([out stringByAppendingPathComponent:[NSString stringWithFormat:@"table-%@.png",ts[i]]],128,128,^{[tc[i]setFill];for(int k=0;k<8;k++){double a=k*M_PI/4;NSBezierPath*c=[NSBezierPath bezierPathWithRoundedRect:NSMakeRect(56+49*cos(a),56+49*sin(a),16,16) xRadius:5 yRadius:5];[c fill];}NSBezierPath*p=[NSBezierPath bezierPathWithOvalInRect:NSMakeRect(22,22,84,84)];[p fill];[gold setStroke];p.lineWidth=2;[p stroke];});}puts("Created 20 PNG UI assets");}return 0;}
